INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20Y0JSO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A plumber charges a flat fee of $\\$47$ for a house call plus $\\$29$ per hour of labor. An electrician charges a flat fee of $\\$83$ plus $\\$17$ per hour. After how many hours of work will the plumber and electrician charge the same total amount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Set the two cost expressions equal: $47 + 29h = 83 + 17h$. Subtract $17h$ from both sides: $47 + 12h = 83$. Subtract 47 from both sides: $12h = 36$. Divide by 12: $h = 3$. After 3 hours, both charge $47 + 29(3) = 134$ dollars.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21IBRKQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 10x + 4y + 13 = 0$. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$\\sqrt{13}$"},{"key":"C","text":"$\\sqrt{42}$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'Completing the square gives $(x^2 - 10x + 25) + (y^2 + 4y + 4) + 13 - 25 - 4 = 0$, which simplifies to $(x - 5)^2 + (y + 2)^2 = 16$. The radius is $\\sqrt{16} = 4$. The value $\\sqrt{13}$ results from mistakenly treating the constant term $13$ as $r^2$. The value $\\sqrt{42}$ comes from adding the completed-square constants ($25 + 4 + 13 = 42$) instead of computing $25 + 4 - 13$. The value $16$ confuses the squared radius $r^2 = 16$ with the radius itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21TCP23', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(7x - 3)(2x + 11)$?', NULL, $lyceon_json$[{"key":"A","text":"$14x^2 + 83x - 33$"},{"key":"B","text":"$14x^2 + 71x - 33$"},{"key":"C","text":"$14x^2 + 71x + 33$"},{"key":"D","text":"$14x^2 - 71x - 33$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the distributive property (FOIL): $(7x)(2x) = 14x^2$, $(7x)(11) = 77x$, $(-3)(2x) = -6x$, and $(-3)(11) = -33$. Combining like terms: $14x^2 + 77x - 6x - 33 = 14x^2 + 71x - 33$. The expression $14x^2 + 83x - 33$ results from adding $77 + 6 = 83$ instead of $77 - 6 = 71$, a sign error on the inner product. The expression $14x^2 + 71x + 33$ has the wrong sign on the constant because $(-3)(11)$ is $-33$, not $+33$. The expression $14x^2 - 71x - 33$ incorrectly negates the entire middle term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22TT2KZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 13x + 36 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 4$ and $x = 9$"},{"key":"B","text":"$x = 3$ and $x = 12$"},{"key":"C","text":"$x = 6$ and $x = 6$"},{"key":"D","text":"$x = -4$ and $x = -9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the quadratic: find two numbers that multiply to $36$ and add to $-13$. Those numbers are $-4$ and $-9$, so $x^2 - 13x + 36 = (x - 4)(x - 9) = 0$. Setting each factor to zero gives $x = 4$ and $x = 9$. The pair $x = 3$ and $x = 12$ has the correct product ($3 \\times 12 = 36$) but the wrong sum ($3 + 12 = 15 \\neq 13$). The pair $x = 6$ and $x = 6$ sums to $12$, not $13$, and although $6 \\times 6 = 36$, equal roots would require a perfect square trinomial. The pair $x = -4$ and $x = -9$ uses the factor magnitudes but applies the wrong signs: $(-4)(-9) = 36$ is correct but $(-4) + (-9) = -13$ gives the original equation $x^2 + 13x + 36 = 0$, not $x^2 - 13x + 36 = 0$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Y7APO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher found that students who ate breakfast daily had higher exam scores than students who skipped breakfast. The data were collected by surveying 250 students about their breakfast habits and comparing their final exam scores. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast daily causes higher exam scores among university students."},{"key":"B","text":"There is an association between eating breakfast daily and higher exam scores among the surveyed students."},{"key":"C","text":"Skipping breakfast causes lower exam scores among all university students."},{"key":"D","text":"Eating breakfast daily and exam scores are unrelated; the difference is due to chance alone."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study is observational (students were surveyed, not randomly assigned to eat or skip breakfast), no causal conclusion can be drawn. The most appropriate conclusion is that there is an association between breakfast habits and exam scores among the surveyed students. Claiming that eating breakfast causes higher scores or that skipping causes lower scores both incorrectly attribute causation to an observational study. Stating the variables are unrelated contradicts the observed data showing a difference between the two groups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM232AVU9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'For the function $g(x) = \\frac{2x^2 - 7x - 15}{x - 5}$, what value does $g(x)$ approach as $x$ approaches $5$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The numerator $2x^2 - 7x - 15$ factors as $(x-5)(2x+3)$. So $g(x) = \\frac{(x-5)(2x+3)}{x-5} = 2x+3$ for $x \\neq 5$. As $x$ approaches $5$, $g(x)$ approaches $2(5) + 3 = 13$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24124LI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = 2x^3 - 9x^2 - 11x + 30$. It is known that $(x - 5)$ is a factor of $p(x)$. Which of the following gives the complete factorization of $p(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 5)(2x^2 + x - 6)$"},{"key":"B","text":"$(x - 5)(2x - 3)(x + 2)$"},{"key":"C","text":"$(x - 5)(2x + 3)(x - 2)$"},{"key":"D","text":"$(x + 5)(2x - 3)(x - 2)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dividing $2x^3 - 9x^2 - 11x + 30$ by $(x-5)$ using synthetic or long division yields $2x^2 + x - 6$. Factoring this quadratic: $2x^2 + x - 6 = (2x - 3)(x + 2)$. So $p(x) = (x-5)(2x-3)(x+2)$. The expression $(x-5)(2x^2+x-6)$ is a valid but incomplete factorization since $2x^2+x-6$ factors further. The expression $(x-5)(2x+3)(x-2)$ results from sign errors in factoring $2x^2+x-6$: $(2x+3)(x-2) = 2x^2 - x - 6$, which has the wrong linear coefficient. The expression $(x+5)(2x-3)(x-2)$ uses $+5$ instead of $-5$ for the known factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24D448B', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'A population of bacteria is modeled by $P(t) = 400 \\cdot 3^t$, where $t$ is measured in hours. By what factor does the population increase every $2$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$9$"},{"key":"C","text":"$3$"},{"key":"D","text":"$800$"}]$lyceon_json$::jsonb, 'B', NULL, E'After $2$ hours, $P(t+2) = 400 \\cdot 3^{t+2} = 400 \\cdot 3^t \\cdot 3^2 = 9 \\cdot P(t)$. The population is multiplied by $9$ every $2$ hours. The factor $6$ confuses $3 \\times 2 = 6$ (multiplying the base by the time instead of raising to the power). The factor $3$ is the growth factor per hour, not per $2$ hours. The value $800$ incorrectly computes $400 \\times 2$, confusing the initial value with the growth factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24KD60M', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A shipping company charges $\\$6$ per package plus a flat route fee. A driver can earn at most $\\$250$ per route. If the flat route fee is $\\$43$, what is the maximum number of packages, $p$, the driver can deliver on one route? Assume the constraint $6p + 43 \\leq 250$.', NULL, $lyceon_json$[{"key":"A","text":"$34$"},{"key":"B","text":"$35$"},{"key":"C","text":"$41$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'A', NULL, E'Solve $6p + 43 \\leq 250$: subtract 43 to get $6p \\leq 207$, then divide by 6 to get $p \\leq 34.5$. Since $p$ must be a whole number, the maximum is $34$. The value $35$ comes from rounding $34.5$ up instead of down when the inequality requires $p \\leq 34.5$. The value $41$ results from dividing $250$ by $6$ without first subtracting the flat fee. The value $48$ comes from an incorrect setup that reverses the roles of the per-package charge and the flat fee.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24NAQDS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills 37 bottles in 4 minutes. At this constant rate, how many bottles does the machine fill in 20 minutes?', NULL, $lyceon_json$[{"key":"A","text":"148"},{"key":"B","text":"185"},{"key":"C","text":"160"},{"key":"D","text":"740"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37}{4}$ bottles per minute, which equals $9.25$ bottles per minute. In 20 minutes the machine fills $9.25 \\times 20 = 185$ bottles. The value 148 results from incorrectly multiplying $37 \\times 4$. The value 160 comes from rounding the rate to 8 bottles per minute. The value 740 comes from multiplying $37 \\times 20$, ignoring that 37 bottles corresponds to 4 minutes, not 1 minute.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25OZDEN', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $3x + 8y = 56$. Line $q$ is perpendicular to line $p$ and passes through the point $(4, -1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{35}{3}$"},{"key":"B","text":"$\\frac{29}{3}$"},{"key":"C","text":"$-\\frac{41}{3}$"},{"key":"D","text":"$\\frac{35}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite line $p$ in slope-intercept form: $8y = -3x + 56$, so $y = -\\frac{3}{8}x + 7$ and the slope of $p$ is $-\\frac{3}{8}$. The perpendicular slope is $\\frac{8}{3}$. Using point-slope form with $(4, -1)$: $y - (-1) = \\frac{8}{3}(x - 4)$, giving $y = \\frac{8}{3}x - \\frac{32}{3} - 1 = \\frac{8}{3}x - \\frac{32}{3} - \\frac{3}{3} = \\frac{8}{3}x - \\frac{35}{3}$. The $y$-intercept is $-\\frac{35}{3}$. The value $\\frac{29}{3}$ comes from adding the constant terms instead of subtracting. The value $-\\frac{41}{3}$ results from an arithmetic slip when combining $-\\frac{32}{3}$ and $-\\frac{3}{3}$, getting $-\\frac{41}{3}$ instead of $-\\frac{35}{3}$. The value $\\frac{35}{3}$ drops the negative sign from the correct answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26ZZ6UZ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If $5(2x^2 - 9x + 4) - 3(x^2 + 7x - 6)$ can be written in the form $ax^2 + bx + c$, what is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-66', ARRAY['-66'], E'Distribute the $5$: $5(2x^2 - 9x + 4) = 10x^2 - 45x + 20$. Distribute the $-3$: $-3(x^2 + 7x - 6) = -3x^2 - 21x + 18$. Combine like terms: $10x^2 - 3x^2 = 7x^2$, $-45x - 21x = -66x$, and $20 + 18 = 38$. The expression simplifies to $7x^2 - 66x + 38$, so $b = -66$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27E0P2O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store marks up an item by 40% over its wholesale cost and then offers a 25% discount on the marked-up price. If the wholesale cost is $\\$62$, what is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$\\$55.80$"},{"key":"B","text":"$\\$65.10$"},{"key":"C","text":"$\\$71.30$"},{"key":"D","text":"$\\$86.80$"}]$lyceon_json$::jsonb, 'B', NULL, E'The marked-up price is $62 \\times 1.40 = \\$86.80$. After a 25% discount the sale price is $86.80 \\times 0.75 = \\$65.10$. The value $\\$55.80$ results from subtracting the two percentages ($40\\% - 25\\% = 15\\%$) and computing $62 \\times 0.90$, a conceptual error. The value $\\$71.30$ comes from an arithmetic slip in multiplying. The value $\\$86.80$ is the marked-up price before the discount is applied.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27EE4CF', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $6x + 19 = 2x + 51$ ?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$32$"},{"key":"D","text":"$8.75$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $2x$ from both sides gives $4x + 19 = 51$. Subtracting 19 from both sides gives $4x = 32$. Dividing both sides by 4 gives $x = 8$. The value $-8$ results from a sign error when isolating the variable. The value $32$ comes from stopping after finding $4x = 32$ without dividing by 4. The value $8.75$ comes from incorrectly adding the $x$-coefficients ($6x + 2x = 8x$) and the constants ($51 + 19 = 70$), yielding $\\frac{70}{8} = 8.75$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27KLXWJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $23$ feet and a width of $17$ feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$80$"},{"key":"B","text":"$391$"},{"key":"C","text":"$400$"},{"key":"D","text":"$351$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a rectangle is length times width: $23 \\times 17 = 391$ square feet. The value $80$ results from computing the perimeter $2(23) + 2(17) = 80$ instead of the area. The value $400$ comes from rounding both dimensions to $20$ before multiplying. The value $351$ results from an arithmetic slip such as computing $23 \\times 15$ instead of $23 \\times 17$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28J42ZN', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{7x - 11}{3} = 2x + 5$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$26$"},{"key":"B","text":"$-26$"},{"key":"C","text":"$16$"},{"key":"D","text":"$-16$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply both sides by 3: $7x - 11 = 6x + 15$. Subtract $6x$ from both sides: $x - 11 = 15$. Add 11 to both sides: $x = 26$. The value $-26$ results from a sign error when moving the constant terms across the equation. The value $16$ comes from an arithmetic slip, adding $11$ and $5$ incorrectly during simplification. The value $-16$ results from combining both errors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28MNLCP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $f$ is defined by $f(x) = x^3 - 6x^2 + 11x - 6$. If $f(1) = 0$, what is the sum of the other two zeros of $f$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Since $f(1) = 0$, $(x - 1)$ is a factor. Dividing $x^3 - 6x^2 + 11x - 6$ by $(x-1)$ gives $x^2 - 5x + 6 = (x-2)(x-3)$. The three zeros are $1$, $2$, and $3$. The sum of the other two zeros is $2 + 3 = 5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28QOVK8', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line in the $xy$-plane passes through the points $(3, 13)$ and $(7, -3)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$25$"},{"key":"C","text":"$-25$"},{"key":"D","text":"$-31$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope of the line is $\\frac{-3 - 13}{7 - 3} = \\frac{-16}{4} = -4$. Using point-slope form with the point $(3, 13)$: $y - 13 = -4(x - 3)$, which simplifies to $y = -4x + 12 + 13 = -4x + 25$. The $y$-intercept is $25$. The value $1$ results from an arithmetic slip such as computing $13 - 12$ instead of $13 + 12$. The value $-25$ results from a sign error applied to the correct magnitude. The value $-31$ results from using a positive slope of $4$ with the point $(7, -3)$: $y + 3 = 4(x - 7)$, giving $y = 4x - 31$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29NUKOI', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $5x + 3 > 48$?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$9$"},{"key":"C","text":"$7$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 3 from both sides gives $5x > 45$, so $x > 9$. Of the choices, only $12$ is greater than $9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29U5FIU', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'In the $xy$-plane, the point $(a, b)$ lies in the solution region of the system of inequalities $y < -2x + 13$ and $y > \\frac{1}{3}x - 4$. Which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"$a < \\frac{51}{7}$"},{"key":"B","text":"$b > 13$"},{"key":"C","text":"$a > \\frac{51}{7}$"},{"key":"D","text":"$b < -4$"}]$lyceon_json$::jsonb, 'A', NULL, E'For $(a, b)$ to satisfy both inequalities, we need $\\frac{1}{3}a - 4 < b < -2a + 13$, which requires $\\frac{1}{3}a - 4 < -2a + 13$. Adding $2a$ and $4$ to both sides gives $\\frac{7}{3}a < 17$, so $a < \\frac{51}{7}$. This must hold for any point in the solution region. The claim $b > 13$ is false because $b < -2a + 13$ means $b$ is strictly less than $-2a + 13$, not necessarily above $13$. The claim $a > \\frac{51}{7}$ reverses the inequality direction from the derivation. The claim $b < -4$ is false because $b > \\frac{1}{3}a - 4$ allows $b$ values well above $-4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AE8YB7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'The function $f$ is defined by $f(x) = 7x - 19$. What is the value of $f(5)$ ?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16', ARRAY['16'], E'Substituting $x = 5$ into the function gives $f(5) = 7(5) - 19 = 35 - 19 = 16$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AEYAB9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = (x - 3)^2 + 11$ reaches its minimum value at which point $(x, y)$ in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$(3, 11)$"},{"key":"B","text":"$(-3, 11)$"},{"key":"C","text":"$(3, -11)$"},{"key":"D","text":"$(-3, -11)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $g(x) = (x-3)^2 + 11$ is in vertex form $a(x-h)^2 + k$, where the vertex is $(h, k) = (3, 11)$. The point $(-3, 11)$ results from using $+3$ instead of recognizing the subtraction gives $h = 3$. The point $(3, -11)$ applies a sign error to the vertical shift. The point $(-3, -11)$ combines both sign errors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AS8HKH', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'The system of equations $7x - 2y = 19$ and $3x + 2y = 31$ has the solution $(x, y)$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'Add the two equations: $(7x - 2y) + (3x + 2y) = 19 + 31$, giving $10x = 50$ and $x = 5$. The value $3$ results from an arithmetic slip when dividing $50$ by $10$ or from subtracting the equations incorrectly. The value $8$ comes from finding $y$ instead of $x$ (substituting $x = 5$ gives $y = 8$) and reporting the wrong variable. The value $12$ results from an incorrect equation setup, such as adding the constants as $19 + 31 = 50$ but then misapplying the coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BAO9H0', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9x^4 - 25y^2}{3x^2 + 5y}$, where $3x^2 + 5y \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^2 + 5y$"},{"key":"B","text":"$3x^2 - 5y$"},{"key":"C","text":"$9x^4 - 5y$"},{"key":"D","text":"$3x^2 - \\frac{5y}{3x^2 + 5y}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9x^4 - 25y^2$ is a difference of squares: $(3x^2)^2 - (5y)^2 = (3x^2 + 5y)(3x^2 - 5y)$. Dividing by $3x^2 + 5y$ cancels that factor, leaving $3x^2 - 5y$. The expression $3x^2 + 5y$ uses the wrong sign from the factored form. The expression $9x^4 - 5y$ incorrectly cancels only the coefficient of the $y^2$ term without proper factoring. The expression $3x^2 - \\frac{5y}{3x^2 + 5y}$ results from splitting the fraction incorrectly instead of factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CJWX0U', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'The system of equations $2x + 5y = 39$ and $2x - 5y = -11$ has the solution $(x, y)$. What is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Subtract the second equation from the first: $(2x + 5y) - (2x - 5y) = 39 - (-11)$, giving $10y = 50$ and $y = 5$. Verification: adding the equations gives $4x = 28$, so $x = 7$. Check: $2(7) + 5(5) = 14 + 25 = 39$ and $2(7) - 5(5) = 14 - 25 = -11$. Both equations are satisfied.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CYSEAP', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A linear function $f$ satisfies $f(3) = 17$ and $f(11) = 53$. What is the value of $f(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/2', ARRAY['7/2', '3.5'], E'The slope is $\\frac{53 - 17}{11 - 3} = \\frac{36}{8} = \\frac{9}{2}$. Using point-slope form with $(3, 17)$: $f(x) = \\frac{9}{2}(x - 3) + 17 = \\frac{9}{2}x - \\frac{27}{2} + \\frac{34}{2} = \\frac{9}{2}x + \\frac{7}{2}$. Therefore $f(0) = \\frac{7}{2}$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DBRB0F', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $DEF$, angle $F$ is the right angle, $DE = 29$, and $DF = 20$. What is the value of $\\sin(D)$, expressed as a fraction?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21/29', ARRAY['21/29', '0.724', '.724'], E'In right triangle $DEF$ with the right angle at $F$, the hypotenuse is $DE = 29$. Using the Pythagorean theorem, $EF = \\sqrt{29^2 - 20^2} = \\sqrt{841 - 400} = \\sqrt{441} = 21$. Since $\\sin(D)$ equals the length of the side opposite angle $D$ divided by the hypotenuse, $\\sin(D) = \\frac{EF}{DE} = \\frac{21}{29}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DZ57S8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 2x^2 + 5$. What is the value of $f(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$77$"},{"key":"B","text":"$17$"},{"key":"C","text":"$67$"},{"key":"D","text":"$149$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 6$ gives $f(6) = 2(6)^2 + 5 = 2(36) + 5 = 72 + 5 = 77$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EOWIPE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The line $y = 7x + 1$ is tangent to the parabola $y = x^2 + 3x + 5$. What is the $y$-coordinate of the point of tangency?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$11$"},{"key":"C","text":"$7$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the expressions equal: $7x + 1 = x^2 + 3x + 5$, which gives $x^2 - 4x + 4 = 0$, or $(x - 2)^2 = 0$. The repeated root $x = 2$ confirms tangency. Substituting into the line: $y = 7(2) + 1 = 15$. The value $11$ results from substituting $x = 2$ into $x^2 + 3x + 5$ but computing $4 + 3 + 5 = 12$ and then subtracting $1$. The value $7$ is the slope of the tangent line, not the $y$-coordinate. The value $29$ results from substituting $x = 4$ instead of $x = 2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EUUI6S', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of the constant $c$ does the system of equations $3x + 5y = 23$ and $cx + 15y = 17$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'C', NULL, E'For a system to have no solution, the lines must be parallel but not coincident. This requires the ratios of corresponding coefficients to be equal while the ratio of constants differs. The coefficient ratio for $y$ is $\\frac{5}{15} = \\frac{1}{3}$. For parallel lines, $\\frac{3}{c} = \\frac{1}{3}$, so $c = 9$. The constant ratio would be $\\frac{23}{17}$, which does not equal $\\frac{1}{3}$, confirming the lines are parallel but not coincident when $c = 9$. The value $3$ does not make the coefficient ratios equal ($\\frac{3}{3} = 1 \\neq \\frac{1}{3}$), so the system would have a unique solution. The value $5$ similarly gives $\\frac{3}{5} \\neq \\frac{1}{3}$, yielding a unique solution. The value $15$ confuses the coefficient of $y$ in the second equation with the needed value of $c$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F9437X', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the sum of all solutions to the equation $|3x - 7| = 11$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14/3', ARRAY['14/3', '4.666', '4.667'], E'Setting up two cases: $3x - 7 = 11$ gives $3x = 18$, so $x = 6$. And $3x - 7 = -11$ gives $3x = -4$, so $x = -\\frac{4}{3}$. The sum is $6 + (-\\frac{4}{3}) = \\frac{18}{3} - \\frac{4}{3} = \\frac{14}{3}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FX3WDN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is formed by placing a hemisphere on top of a right circular cylinder. Both the hemisphere and the cylinder have a radius of $5$ cm, and the cylinder has a height of $13$ cm. What is the total volume of the solid, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1225\\pi}{3}$"},{"key":"B","text":"$\\frac{1475\\pi}{3}$"},{"key":"C","text":"$325\\pi$"},{"key":"D","text":"$\\frac{1100\\pi}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The cylinder volume is $\\pi r^2 h = \\pi(25)(13) = 325\\pi$. The hemisphere volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(125) = \\frac{250\\pi}{3}$. The total is $325\\pi + \\frac{250\\pi}{3} = \\frac{975\\pi}{3} + \\frac{250\\pi}{3} = \\frac{1225\\pi}{3}$. The value $\\frac{1475\\pi}{3}$ results from using the full sphere volume $\\frac{4}{3}\\pi(125) = \\frac{500\\pi}{3}$ instead of a hemisphere. The value $325\\pi$ accounts for only the cylinder and omits the hemisphere entirely. The value $\\frac{1100\\pi}{3}$ comes from an arithmetic error in computing $975 + 250$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G7CZHV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours of sunlight per day ($x$) and the average daily temperature in degrees Fahrenheit ($y$) for 30 days. The line of best fit is $y = 3.7x + 19.4$. What is the best interpretation of the slope in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight, the predicted average temperature increases by $3.7°\\text{F}$."},{"key":"B","text":"For each additional degree Fahrenheit, the predicted sunlight increases by $3.7$ hours."},{"key":"C","text":"When there are zero hours of sunlight, the predicted temperature is $3.7°\\text{F}$."},{"key":"D","text":"For each additional hour of sunlight, the predicted average temperature increases by $19.4°\\text{F}$."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 3.7x + 19.4$, the slope $3.7$ represents the predicted change in $y$ (temperature) for each one-unit increase in $x$ (hours of sunlight). So each additional hour of sunlight corresponds to a predicted temperature increase of $3.7°\\text{F}$. Interpreting the slope as change in sunlight per degree reverses the roles of the variables. Stating that the predicted temperature at zero sunlight is $3.7$ confuses the slope with the $y$-intercept. Claiming the temperature increases by $19.4$ per hour swaps the slope and intercept values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HJPSZP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 + 5x = 84$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Rewrite the equation in standard form: $x^2 + 5x - 84 = 0$. Factor by finding two numbers that multiply to $-84$ and add to $5$. Those numbers are $12$ and $-7$, since $12 \\times (-7) = -84$ and $12 + (-7) = 5$. So $x^2 + 5x - 84 = (x + 12)(x - 7) = 0$. Setting each factor to zero gives $x = -12$ or $x = 7$. The positive value is $7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IIY9MP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is one solution to the equation $x^2 - 15x + 54 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring gives $(x - 6)(x - 9) = 0$, so $x = 6$ or $x = 9$. Since $6$ appears among the choices, it is a valid answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ISYUJY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A gym membership costs $\\$53$ to join and $\\$19$ per month. The function $C(m) = 19m + 53$ gives the total cost in dollars after $m$ months. What is the best interpretation of the number $19$ in this function?', NULL, $lyceon_json$[{"key":"A","text":"The total cost increases by $\\$19$ each month."},{"key":"B","text":"The initial cost of joining the gym is $\\$19$."},{"key":"C","text":"The total cost after $19$ months of membership."},{"key":"D","text":"The minimum number of months required for the membership."}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $C(m) = 19m + 53$, the coefficient $19$ is the rate of change, meaning the total cost increases by $\\$19$ for each additional month. Interpreting $19$ as the initial joining cost confuses the slope with the $y$-intercept ($53$). Interpreting $19$ as a number of months confuses a coefficient with an input value. Interpreting $19$ as a minimum membership length has no basis in the function definition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JDK63X', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the solution $(x, y)$ to the system of equations $x + y = 13$ and $x - y = 5$?', NULL, $lyceon_json$[{"key":"A","text":"$(8, 5)$"},{"key":"B","text":"$(9, 4)$"},{"key":"C","text":"$(5, 8)$"},{"key":"D","text":"$(4, 9)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations: $(x + y) + (x - y) = 13 + 5$, so $2x = 18$ and $x = 9$. Substituting into $x + y = 13$: $9 + y = 13$, so $y = 4$. The solution is $(9, 4)$. The pair $(8, 5)$ results from an arithmetic slip when computing $18 \\div 2$ or mishandling the addition. The pair $(5, 8)$ swaps the $x$- and $y$-values. The pair $(4, 9)$ also reverses the coordinates, assigning the $y$-value to $x$ and vice versa.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JJF8S3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed at the first intersection measures $131°$. A triangle is formed using parts of the two parallel lines and the transversal. If one base angle of this triangle is the supplement of $131°$ and the other base angle measures $37°$, what is the measure, in degrees, of the third angle of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$94$"},{"key":"B","text":"$86$"},{"key":"C","text":"$96$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'A', NULL, E'The supplement of $131°$ is $180° - 131° = 49°$. The three angles of the triangle sum to $180°$, so the third angle is $180° - 49° - 37° = 94°$. The value $86$ comes from an arithmetic error such as using $57°$ instead of $37°$ for the second base angle. The value $96$ arises from miscalculating the supplement as $51°$ and then computing $180 - 51 - 37 = 92$, with a further slip to $96$. The value $49$ mistakes the supplementary angle itself for the third angle of the triangle.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JQ92JM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $12$ and the hypotenuse has length $37$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$35$"},{"key":"B","text":"$25$"},{"key":"C","text":"$49$"},{"key":"D","text":"$\\sqrt{1513}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the Pythagorean theorem, the other leg is $\\sqrt{37^2 - 12^2} = \\sqrt{1369 - 144} = \\sqrt{1225} = 35$.', $lyceon_json${"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"A":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KOUKL0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = -4x + b$, where $b$ is a constant. If $g(11) = 3$, what is the value of $b$ ?', NULL, $lyceon_json$[{"key":"A","text":"$-41$"},{"key":"B","text":"$7$"},{"key":"C","text":"$47$"},{"key":"D","text":"$-47$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 11$ into $g(x) = -4x + b$ gives $g(11) = -4(11) + b = -44 + b$. Setting this equal to 3: $-44 + b = 3$, so $b = 47$. The value $-41$ results from incorrectly computing $-4(11)$ as $44$ (sign error), yielding $44 + b = 3$ and $b = -41$. The value $7$ results from an arithmetic slip such as subtracting $4$ from $11$ instead of multiplying. The value $-47$ results from negating the correct answer due to a sign error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KX0UKJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 400 registered voters in a city found that 58% support a proposed parks initiative, with a margin of error of 4 percentage points. Which of the following is the most accurate interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between 54% and 62% of the sampled voters support the initiative."},{"key":"B","text":"It is plausible that between 54% and 62% of all registered voters in the city support the initiative."},{"key":"C","text":"Exactly 58% of all registered voters in the city support the initiative."},{"key":"D","text":"If another sample of 400 voters is taken, exactly 58% will support the initiative."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 4 percentage points means the confidence interval for the true population proportion is $58\\% \\pm 4\\%$, or between 54% and 62%. This interval applies to the entire population of registered voters, not just the sample. Stating the interval describes the sampled voters confuses the sample statistic with the population estimate. Claiming exactly 58% ignores the uncertainty inherent in sampling. Asserting a future sample will yield the same result misunderstands sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NJ4FG6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $7$ cm and a height of $11$ cm. What is the volume of the cylinder, in cubic centimeters? (Use $\\pi \\approx \\frac{22}{7}$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1694', ARRAY['1694'], E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $\\pi \\approx \\frac{22}{7}$, $r = 7$, and $h = 11$: $V = \\frac{22}{7} \\times 7^2 \\times 11 = \\frac{22}{7} \\times 49 \\times 11 = 22 \\times 7 \\times 11 = 1694$ cubic centimeters.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OGRT1E', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(2x^2 - 7x + 4) - 2(x^2 + 5x - 3)$?', NULL, $lyceon_json$[{"key":"A","text":"$4x^2 - 31x + 18$"},{"key":"B","text":"$4x^2 - 11x + 6$"},{"key":"C","text":"$4x^2 - 31x + 6$"},{"key":"D","text":"$5x^2 - 31x + 18$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the $3$ gives $6x^2 - 21x + 12$, and distributing the $-2$ gives $-2x^2 - 10x + 6$. Adding these: $(6-2)x^2 + (-21-10)x + (12+6) = 4x^2 - 31x + 18$. The expression $4x^2 - 11x + 6$ results from failing to distribute the negative sign to the $5x$ term. The expression $4x^2 - 31x + 6$ results from computing $12 - 6 = 6$ instead of $12 + 6 = 18$. The expression $5x^2 - 31x + 18$ results from computing $6 - 1 = 5$ instead of $6 - 2 = 4$ for the leading coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OHEWCL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The data set $\\{18, 23, 23, 27, 31, 34, 41\\}$ represents the ages of participants in a workshop. If the value 41 is replaced by 53, which of the following measures changes?', NULL, $lyceon_json$[{"key":"A","text":"Mean only"},{"key":"B","text":"Median only"},{"key":"C","text":"Both mean and median"},{"key":"D","text":"Neither mean nor median"}]$lyceon_json$::jsonb, 'A', NULL, E'The original mean is $\\frac{18+23+23+27+31+34+41}{7} = \\frac{197}{7} \\approx 28.14$. Replacing 41 with 53 raises the sum by 12, changing the mean to $\\frac{209}{7} \\approx 29.86$. The median is the 4th value in the ordered set, which is 27 both before and after the change, since only the largest value was altered. Therefore only the mean changes. Choosing the median only reflects a misunderstanding of how extreme values affect the median. Choosing both incorrectly assumes the median also shifts when the maximum increases. Choosing neither fails to recognize that the mean depends on the sum of all values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P0RZ8Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $53°$ and the measure of angle $Q$ is $72°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$55$"},{"key":"B","text":"$65$"},{"key":"C","text":"$45$"},{"key":"D","text":"$125$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is $180°$. Therefore, $R = 180° - 53° - 72° = 55°$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PYWU54', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $2x^2 + 13x - 24 = 0$, what is the positive value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{2}$"},{"key":"B","text":"$4$"},{"key":"C","text":"$\\frac{8}{3}$"},{"key":"D","text":"$\\frac{24}{13}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the quadratic formula or factoring: $2x^2 + 13x - 24 = (2x - 3)(x + 8) = 0$. This gives $x = \\frac{3}{2}$ or $x = -8$. The positive solution is $\\frac{3}{2}$. The value $4$ results from incorrectly factoring as $(2x - 8)(x + 3)$, which expands to $2x^2 - 2x - 24$, not the original. The value $\\frac{8}{3}$ comes from an arithmetic error in the quadratic formula. The value $\\frac{24}{13}$ comes from incorrectly dividing the constant by the linear coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RVYURH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In 2023 a town''s population was 14,700. If the population had increased by 12% from 2021 to 2022 and then decreased by 5% from 2022 to 2023, what was the approximate population in 2021?', NULL, $lyceon_json$[{"key":"A","text":"13,810"},{"key":"B","text":"13,618"},{"key":"C","text":"14,500"},{"key":"D","text":"13,824"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $P$ be the 2021 population. After a 12% increase: $1.12P$. After a 5% decrease: $1.12P \\times 0.95 = 1.064P$. Setting $1.064P = 14{,}700$ gives $P = \\frac{14{,}700}{1.064} \\approx 13{,}816$, which is closest to 13,810 among the given choices. The value 13,618 results from incorrectly computing $14{,}700 \\div 1.0794$ using a different combined factor. The value 14,500 comes from only reversing the 5% decrease and ignoring the 12% increase. The value 13,824 arises from an arithmetic rounding slip in the division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SLM2EQ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'If $-\\frac{2}{5}x + 13 \\geq 7$, what is the greatest integer value of $x$ that satisfies the inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'Subtract 13 from both sides: $-\\frac{2}{5}x \\geq -6$. Multiply both sides by $-\\frac{5}{2}$ and reverse the inequality sign: $x \\leq 15$. The greatest integer satisfying $x \\leq 15$ is $15$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SZ19IU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the points $(2, 9)$ and $(6, 21)$. What is the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{3}$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{21 - 9}{6 - 2} = \\frac{12}{4} = 3$. The value $\\frac{1}{3}$ results from inverting the slope formula, dividing the change in $x$ by the change in $y$. The value $-3$ comes from introducing an incorrect negative sign during the subtraction step. The value $12$ results from computing only the numerator of the slope formula without dividing by the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UDIDBV', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq \\frac{2}{3}$, which expression is equivalent to $\\frac{6x^2 + 17x - 14}{3x - 2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x - 7$"},{"key":"B","text":"$2x + 5$"},{"key":"C","text":"$2x + 7$"},{"key":"D","text":"$3x + 7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Perform polynomial long division of $6x^2 + 17x - 14$ by $3x - 2$. First, $6x^2 \\div 3x = 2x$. Multiply: $2x(3x - 2) = 6x^2 - 4x$. Subtract: $(6x^2 + 17x - 14) - (6x^2 - 4x) = 21x - 14$. Next, $21x \\div 3x = 7$. Multiply: $7(3x - 2) = 21x - 14$. Subtract: $(21x - 14) - (21x - 14) = 0$. The quotient is $2x + 7$ with no remainder. The expression $2x - 7$ results from a sign error in the subtraction step. The expression $2x + 5$ comes from an arithmetic mistake when computing $17x - (-4x)$. The expression $3x + 7$ results from incorrectly dividing $6x^2 \\div 2 = 3x$ instead of $6x^2 \\div 3x = 2x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V3RR87', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 49}{2x^2 + 5x - 7}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2x + 7}{x - 1}$"},{"key":"B","text":"$\\frac{2x - 7}{x - 1}$"},{"key":"C","text":"$\\frac{2x - 7}{x + 1}$"},{"key":"D","text":"$\\frac{2x - 7}{2x + 5}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator as a difference of squares: $4x^2 - 49 = (2x - 7)(2x + 7)$. Factor the denominator: $2x^2 + 5x - 7 = (x - 1)(2x + 7)$, since $(x - 1)(2x + 7) = 2x^2 + 7x - 2x - 7 = 2x^2 + 5x - 7$. Cancel the common factor $(2x + 7)$, yielding $\\frac{2x - 7}{x - 1}$. The expression $\\frac{2x + 7}{x - 1}$ cancels the wrong factor from the numerator, keeping $(2x + 7)$ instead of $(2x - 7)$. The expression $\\frac{2x - 7}{x + 1}$ has a sign error in factoring the denominator. The expression $\\frac{2x - 7}{2x + 5}$ incorrectly divides the denominator''s coefficients rather than properly factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V43EFH', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3x^2 + 21x$?', NULL, $lyceon_json$[{"key":"A","text":"$3x(x + 7)$"},{"key":"B","text":"$3(x^2 + 7)$"},{"key":"C","text":"$x(3x + 7)$"},{"key":"D","text":"$3x(x + 21)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring $3x^2 + 21x$, the greatest common factor of both terms is $3x$. Dividing each term by $3x$ gives $x + 7$, so $3x^2 + 21x = 3x(x + 7)$. The expression $3(x^2 + 7)$ only factors out $3$, not the common $x$ factor, so it omits the $x$ from the second term''s factoring. The expression $x(3x + 7)$ expands to $3x^2 + 7x$, which differs from the original because $7x \\neq 21x$. The expression $3x(x + 21)$ incorrectly divides only the first term by $3x$ and leaves $21$ undivided.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VQRKCM', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $x$ in the equation $7x - 23 = 54$ ?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Adding 23 to both sides of the equation gives $7x = 77$. Dividing both sides by 7 gives $x = 11$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VRVNUN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = -2(x + 4)^2 + 18$. For what value of $x$ does $h(x)$ reach its maximum?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$18$"},{"key":"D","text":"$-18$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $h(x) = -2(x+4)^2 + 18$ is in vertex form with vertex at $(-4, 18)$. Since the leading coefficient is negative, the parabola opens downward and the vertex is a maximum. The maximum occurs at $x = -4$. The value $4$ applies the wrong sign to the horizontal shift. The value $18$ is the maximum output, not the input where it occurs. The value $-18$ applies a sign error to the vertical shift.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VS7OMH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $(x, y)$ is the solution to the system below where $x > 0$, what is the value of $x + y$? $$x^2 + y^2 = 41$$ $$x - y = 1$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'From the second equation, $x = y + 1$. Substituting into the first: $(y+1)^2 + y^2 = 41$, which gives $y^2 + 2y + 1 + y^2 = 41$, so $2y^2 + 2y - 40 = 0$, or $y^2 + y - 20 = 0$. Factoring: $(y+5)(y-4) = 0$, so $y = -5$ or $y = 4$. When $y = 4$, $x = 5$ (positive). When $y = -5$, $x = -4$ (negative). Since $x > 0$, the solution is $(5, 4)$ and $x + y = 9$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W13MH7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'grid_in', E'A jar contains 13 red marbles, 9 blue marbles, and 3 green marbles. If one marble is drawn at random, what is the probability that it is NOT blue? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16/25', ARRAY['16/25', '0.64', '.64'], E'The total number of marbles is $13 + 9 + 3 = 25$. The number of marbles that are not blue is $25 - 9 = 16$. Therefore the probability of drawing a marble that is not blue is $\\frac{16}{25}$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W4NKBN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle in the $xy$-plane passes through the points $(1, 7)$, $(13, 7)$, and $(13, 2)$. What is the diameter of this circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The perpendicular bisector of the segment from $(1, 7)$ to $(13, 7)$ is the vertical line $x = 7$. The perpendicular bisector of the segment from $(13, 7)$ to $(13, 2)$ is the horizontal line $y = 4.5$. The center of the circle is at their intersection, $(7, 4.5)$. The radius is the distance from the center to any of the three points: $r = \\sqrt{(7 - 1)^2 + (4.5 - 7)^2} = \\sqrt{36 + 6.25} = \\sqrt{42.25} = 6.5$. The diameter is $2 \\times 6.5 = 13$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X7DS4Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A recipe uses $\\frac{7}{3}$ cups of sugar for every 11 servings. How many cups of sugar are needed for 33 servings?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Since 33 servings is $\\frac{33}{11} = 3$ times the base amount of 11 servings, the sugar needed is $3 \\times \\frac{7}{3} = 7$ cups.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X7UG6N', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = -\\frac{4}{7}x + b$, where $b$ is a constant. The equation $y = g(x)$ is satisfied by the point $(14, -3)$. If $g(k) = 13$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-28$"},{"key":"B","text":"$-14$"},{"key":"C","text":"$14$"},{"key":"D","text":"$-\\frac{91}{4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find $b$ using the point $(14, -3)$: $-3 = -\\frac{4}{7}(14) + b = -8 + b$, so $b = 5$. Now solve $g(k) = 13$: $-\\frac{4}{7}k + 5 = 13$, giving $-\\frac{4}{7}k = 8$ and $k = 8 \\times (-\\frac{7}{4}) = -14$. The value $-28$ results from using $b = -3$ directly instead of solving for $b$, leading to $-\\frac{4}{7}k - 3 = 13$ and $k = -28$. The value $14$ comes from a sign error, using a positive slope $\\frac{4}{7}$ instead of $-\\frac{4}{7}$. The value $-\\frac{91}{4}$ results from omitting the step of finding $b$ and solving $-\\frac{4}{7}k = 13$ directly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XAF6X8', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $5x - 7y = 35$ represents a line in the $xy$-plane. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -5)$"},{"key":"B","text":"$(0, 5)$"},{"key":"C","text":"$(0, 7)$"},{"key":"D","text":"$(0, -7)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set $x = 0$: $5(0) - 7y = 35$, so $-7y = 35$ and $y = -5$. The $y$-intercept is $(0, -5)$. The point $(0, 5)$ results from dropping the negative sign when dividing $35$ by $-7$. The point $(0, 7)$ comes from confusing the coefficient of $y$ with the intercept value. The point $(0, -7)$ results from reading the coefficient of $y$ directly as the $y$-coordinate of the intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW215MM9H', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geologists studying the Deccan Traps, a vast volcanic province in western India, have long debated whether the eruptions contributed to the mass extinction at the end of the Cretaceous period. Recent argon-argon dating of lava flows suggests that the most intense phase of volcanism began approximately 250,000 years before the asteroid impact at Chicxulub. __________, the volcanic emissions may have already destabilized global ecosystems, making them more vulnerable to the catastrophic effects of the subsequent impact.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"If so,"},{"key":"C","text":"For instance,"},{"key":"D","text":"On the contrary,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "If so," because the second sentence draws a conditional inference from the dating evidence presented in the preceding sentence: if the intense volcanism indeed began before the impact, then the emissions may have weakened ecosystems beforehand. "Nevertheless" incorrectly signals a concession, implying the second claim holds despite the first, but the second sentence builds on the first rather than contradicting it. "For instance" would introduce a specific example, yet the sentence presents a broader implication, not an illustration. "On the contrary" signals a direct contradiction of the previous point, which misrepresents the logical relationship entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21E8DTT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A team of geologists studying volcanic rock formations in the Azores recently published a paper on basalt weathering patterns. The lead researcher, Dr. Fernanda Oliveira, _______ that certain mineral deposits in the region are significantly older than previous estimates suggested.', $lyceon_json$[{"key":"A","text":"are arguing"},{"key":"B","text":"argue"},{"key":"C","text":"argues"},{"key":"D","text":"have been arguing"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the verb is "The lead researcher, Dr. Fernanda Oliveira," which is a singular noun phrase. The appositive "Dr. Fernanda Oliveira" is set off by commas and renames the singular subject "The lead researcher." A singular subject requires a singular verb form. "argues" is the correct third-person singular present-tense form. "are arguing" uses the plural auxiliary "are," which does not agree with the singular subject. "argue" is the bare plural form, which does not agree with the singular subject. "have been arguing" uses the plural auxiliary "have," which does not agree with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22J0ORV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, the architect Lena Johansson proposed a radical redesign of the municipal library in Gothenburg. Her plan called for replacing the building''s limestone facade with panels of recycled _______ the city council, however, rejected the proposal on the grounds that it clashed with the surrounding historic district.', $lyceon_json$[{"key":"A","text":"glass, but"},{"key":"B","text":"glass;"},{"key":"C","text":"glass"},{"key":"D","text":"glass, meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage contains two independent clauses. The second clause begins with "the city council, however, rejected the proposal," where "however" is a conjunctive adverb set off by commas, not a coordinating conjunction. A semicolon before this construction is the correct boundary punctuation. "glass;" properly separates the two independent clauses with a semicolon before the conjunctive adverb "however." "glass, but" would introduce a redundant contrast marker: "but" signals contrast, and "however" in the next clause also signals contrast, creating an awkward double-contrast construction; moreover, the clause after the comma already contains its own internal commas around "however," making the sentence structure unclear. "glass" alone creates a run-on with no punctuation between independent clauses. "glass, meanwhile," produces a comma splice and incorrectly substitutes "meanwhile" (which signals simultaneous timing) for a contrast relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW234KEEL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'In 1966, the architect Denys Lasdun completed the Royal College of Physicians building in London, a striking Brutalist structure that juts dramatically from its Georgian surroundings on the edge of Regent''s Park. Critics at the time condemned the building as an affront to the neighborhood''s classical character. __________, architectural historians now regard the building''s deliberate tension with its context as one of its greatest achievements, arguing that Lasdun designed the contrast not as a provocation but as a dialogue between historical periods.', $lyceon_json$[{"key":"A","text":"In much the same manner,"},{"key":"B","text":"That is,"},{"key":"C","text":"Surprisingly, however,"},{"key":"D","text":"As a direct consequence,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "Surprisingly, however," because the passage shifts from the critics'' negative reception to the modern historians'' positive reassessment, and the reversal in judgment is presented as unexpected. "In much the same manner" incorrectly signals that the historians'' view echoes the critics'' condemnation, when in fact the two perspectives are opposed. "That is" signals a restatement or clarification, but the historians'' view is a substantively different claim, not a rephrasing of the original criticism. "As a direct consequence" implies the historians'' positive assessment was caused by the criticism, but the passage presents the reassessment as a surprising reversal, not a logical outcome of the earlier negative reception.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23QFUUB', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Sociologist Elena Vargas asserts that remote work has fundamentally weakened workplace solidarity. She points to survey data from eleven multinational firms showing that employees who work from home more than three days per week report thirty-seven percent fewer informal conversations with colleagues and are half as likely to participate in collective bargaining efforts.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW244O5ER', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economist Priya Deshpande studied wage patterns among seasonal agricultural workers in the Indian state of Maharashtra between 2018 and 2023. She found that villages where workers had access to a government-funded vocational training program saw average daily wages rise by 23 percent over the period, while wages in comparable villages without the program rose by only 9 percent. However, Deshpande also noted that trained workers increasingly migrated to urban areas after completing the program, leaving fewer laborers available during peak harvest months. Farm owners in program villages therefore had to offer higher wages to attract the remaining local workers. This finding complicates the interpretation that the wage increase directly reflects ________', $lyceon_json$[{"key":"A","text":"improved productivity among trained workers, since the rise may partly stem from a reduced local labor supply."},{"key":"B","text":"a nationwide trend of increasing agricultural wages across all Indian states during this period."},{"key":"C","text":"the program's failure to equip workers with skills relevant to agricultural tasks performed during harvest."},{"key":"D","text":"declining crop yields that forced farm owners to compensate workers at rates above market value."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that trained workers migrated to urban areas, reducing the local labor supply, which forced farm owners to raise wages. This means the wage increase may reflect labor scarcity rather than improved worker productivity from training. The completion about improved productivity being complicated by reduced labor supply logically follows from the passage''s evidence. The choice about a nationwide wage trend introduces information not discussed in the passage and does not connect to the specific mechanism the passage describes. The choice about the program failing to provide relevant skills contradicts the passage, which does not suggest the training was irrelevant but rather that trained workers left for urban employment. The choice about declining crop yields introduces an entirely unsupported factor; the passage attributes the wage increase to labor migration, not to any change in crop production.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24GCNKZ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes data from the study that would weaken the committee''s conclusion?', E'A municipal planning committee in Brindisi, Italy, concluded in a 2023 report that converting the city''s remaining 1,400 diesel buses to electric models would reduce citywide nitrogen dioxide emissions by at least 35 percent. The committee based this projection on a pilot program in which 19 diesel buses operating on Route 7 were replaced with electric vehicles. During the six-month pilot, nitrogen dioxide levels at monitoring stations along Route 7 declined by 38 percent compared to the same period the previous year.', $lyceon_json$[{"key":"A","text":"Route 7 passes through a narrow valley where air pollutants disperse more slowly than in other parts of Brindisi, amplifying the measured effect of removing diesel emissions sources."},{"key":"B","text":"The electric buses used in the pilot consumed 12 percent less energy per kilometer than the committee had projected, lowering operating costs."},{"key":"C","text":"Several other Italian cities have adopted electric buses and reported nitrogen dioxide reductions of between 20 and 40 percent on converted routes."},{"key":"D","text":"During the pilot period, a regional industrial facility near Route 7 temporarily suspended operations for scheduled maintenance, also reducing nitrogen dioxide output in that area."}]$lyceon_json$::jsonb, 'A', NULL, E'The committee generalized from Route 7''s 38 percent reduction to project a citywide reduction of at least 35 percent. If Route 7 runs through a narrow valley where pollutants disperse more slowly, the measured reduction on that route would overstate the effect expected in other areas of Brindisi, weakening the citywide projection. The finding about lower energy consumption addresses operating costs rather than emissions reductions and does not challenge the emissions estimate. The finding about other Italian cities reporting similar reductions would, if anything, support the committee''s conclusion rather than weaken it. The finding about an industrial facility suspending operations does suggest a confounding factor, but the question asks which data from the study itself would weaken the conclusion; the geographic peculiarity of Route 7 is a structural feature of the study design that undermines its generalizability, making it the strongest answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW261Y7GL', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologist Carla Espinoza has spent fourteen years studying the feeding patterns of leatherback sea turtles in the eastern Pacific. Her team''s 2023 survey documented that leatherbacks near the coast of Peru consume an average of 73 kilograms of jellyfish per day during peak migration months. This consumption rate, Espinoza argues, makes leatherbacks a keystone regulator of jellyfish populations in regions where overfishing has removed competing predators. Without leatherbacks, jellyfish blooms would likely intensify, disrupting local fisheries that depend on larval fish survival.', $lyceon_json$[{"key":"A","text":"Leatherback sea turtles consume jellyfish at a rate that plays a critical role in controlling jellyfish populations in the eastern Pacific."},{"key":"B","text":"Carla Espinoza's research team conducted a survey near Peru's coast to measure the weight of jellyfish species found in that region."},{"key":"C","text":"Overfishing in the eastern Pacific has eliminated most predators that previously competed with leatherback sea turtles for food sources."},{"key":"D","text":"Jellyfish blooms have already caused severe damage to local fisheries along the Peruvian coastline due to declining turtle populations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Espinoza''s finding that leatherbacks consume large quantities of jellyfish and thereby regulate jellyfish populations, making the choice about leatherbacks playing a critical role in controlling jellyfish populations the best statement of the main idea. The choice about measuring jellyfish weight misreads the purpose of the survey, which measured turtle consumption rather than jellyfish weight. The choice about overfishing eliminating most competing predators overstates a supporting detail; the passage mentions overfishing as context but does not claim most predators were eliminated. The choice about jellyfish blooms already damaging fisheries goes beyond the text, which presents intensified blooms as a hypothetical consequence, not an established fact.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW265M049', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Sven Lindgren''s excavation of a Bronze Age settlement on the Swedish island of Gotland uncovered 47 ceramic vessels bearing decorative motifs previously associated exclusively with communities on the Baltic coast of modern-day Latvia. Conventional interpretations would attribute these vessels to long-distance trade, but Lindgren''s petrographic analysis revealed that the clay used in 39 of the 47 vessels was sourced from deposits local to Gotland. Furthermore, trace-element profiles of the remaining 8 vessels matched clay sources in eastern Latvia. Lindgren argues that these findings, taken together, most likely indicate that ________', $lyceon_json$[{"key":"A","text":"Latvian-trained potters relocated to Gotland and produced vessels using local materials while retaining their traditional decorative techniques."},{"key":"B","text":"Gotland's potters independently developed decorative styles identical to those of Latvian communities through convergent cultural evolution."},{"key":"C","text":"The 47 vessels were all manufactured in Latvia and transported to Gotland, but some were made using clay that Latvian potters had imported from Gotland."},{"key":"D","text":"Bronze Age communities on Gotland traded raw clay to Latvian settlements in exchange for finished ceramic vessels decorated with Latvian motifs."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two key facts: most vessels use Gotland-local clay yet bear Latvian decorative motifs, and a smaller group uses Latvian clay. The most logical inference is that Latvian-trained artisans moved to Gotland, initially bringing some vessels from Latvia (the 8 with Latvian clay) and then producing new ones locally while maintaining their decorative traditions (the 39 with Gotland clay). The choice about convergent cultural evolution is implausible given the specificity of the motifs and ignores the 8 vessels made from Latvian clay, which demonstrate a direct connection to Latvia. The choice about all 47 vessels being manufactured in Latvia requires the unlikely scenario that Latvian potters imported Gotland clay for 39 of the vessels, which the passage does not suggest and would be economically impractical. The choice about Gotland trading raw clay for finished vessels contradicts the petrographic evidence showing that most vessels with Latvian motifs were made from local Gotland clay rather than being imported as finished products.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26X7GSN', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which choice most effectively uses data from the passage to support Vasquez''s claim?', E'Sociologist Elena Vasquez argues that urban residents who commute by bicycle report higher overall life satisfaction not because cycling itself improves mood but because cyclists tend to live in neighborhoods with greater access to green spaces, cultural venues, and pedestrian infrastructure. She points to her 2024 survey of 2,300 adults across seven mid-sized European cities, in which respondents rated their life satisfaction on a 1-to-10 scale. Among respondents living in neighborhoods classified as having high walkability scores, the average life satisfaction rating was 7.9 for cyclists and 7.7 for non-cyclists. Among respondents in neighborhoods with low walkability scores, the average rating was 6.1 for cyclists and 5.9 for non-cyclists.', $lyceon_json$[{"key":"A","text":"In both high- and low-walkability neighborhoods, the difference in life satisfaction between cyclists and non-cyclists was small compared to the difference between high- and low-walkability neighborhoods overall."},{"key":"B","text":"Cyclists in high-walkability neighborhoods reported a life satisfaction rating of 7.9, which was the highest average rating among all four groups in the survey."},{"key":"C","text":"Non-cyclists in low-walkability neighborhoods reported the lowest average life satisfaction of any group, suggesting that both cycling and neighborhood quality independently affect well-being."},{"key":"D","text":"The survey included 2,300 adults from seven European cities, giving Vasquez a sufficiently large and geographically diverse sample to draw reliable conclusions about cycling and mood."}]$lyceon_json$::jsonb, 'A', NULL, E'Vasquez claims that neighborhood characteristics, not cycling itself, drive the satisfaction gap. The data show that the cyclist vs. non-cyclist gap is only 0.2 points in both neighborhood types, while the gap between high- and low-walkability neighborhoods is approximately 1.8 points. Noting that the neighborhood difference dwarfs the cycling difference directly supports her claim. The choice highlighting cyclists in high-walkability neighborhoods having the highest rating merely identifies the top group without comparing the relative magnitudes of the two factors, so it does not isolate neighborhood quality as the dominant variable. The choice about non-cyclists in low-walkability neighborhoods having the lowest rating interprets the data as showing independent effects of both cycling and neighborhood quality, which contradicts Vasquez''s argument that neighborhood quality is the primary driver. The choice about sample size addresses methodological credibility rather than presenting data that supports the specific claim about neighborhood characteristics versus cycling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW281SDQC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing a report on coral reef monitoring, a researcher wants to highlight the advantage that acoustic methods offer over traditional visual surveys. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29CIKZG', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The northern quoll, a small marsupial carnivore native to Australia, has experienced significant population declines due to the spread of invasive cane toads. Quolls that attempt to eat the toxic toads almost invariably die. __________, researchers at the University of Melbourne have begun training captive quolls to avoid cane toads by feeding them small, non-lethal toad sausages laced with a nausea-inducing chemical.', $lyceon_json$[{"key":"A","text":"In comparison,"},{"key":"B","text":"In response,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "In response," because the researchers'' training program is a direct reaction to the problem of quolls dying from eating cane toads. "In comparison" incorrectly signals a parallel between two similar items, but no comparison is being drawn. "Regardless" implies the second sentence proceeds despite the first, which mischaracterizes the causal relationship. "In other words" signals a restatement, but the researchers'' intervention is new information, not a rephrasing of the population decline.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A4UH5E', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing about the history of synthetic dyes, a student wants to present an ironic contrast between William Henry Perkin''s original intention and the actual outcome of his 1856 experiment. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B1KA8J', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The conservationist Yuki Tanabe has spent over a decade restoring wetland habitats along the Shinano River. Tanabe''s most ambitious project, which involved transplanting native sedge grasses across nineteen hectares of degraded floodplain, _______ by the time a provincial review board evaluated the site in March 2023.', $lyceon_json$[{"key":"A","text":"was already yielding measurable ecological improvements"},{"key":"B","text":"has already yielded measurable ecological improvements"},{"key":"C","text":"had already yielded measurable ecological improvements"},{"key":"D","text":"already yields measurable ecological improvements"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence describes an action that was completed before another past event: the project yielded improvements before the review board evaluated the site in March 2023. This sequence requires the past perfect tense. "had already yielded measurable ecological improvements" correctly uses the past perfect to indicate that the yielding was completed prior to the past-tense evaluation. "was already yielding measurable ecological improvements" uses the past progressive, which indicates an ongoing action at the time of the evaluation rather than a completed one, failing to convey that the results preceded the review. "has already yielded measurable ecological improvements" uses the present perfect, which connects a past action to the present moment; this tense is incorrect because the sentence anchors both events firmly in the past with the specific date "March 2023." "already yields measurable ecological improvements" uses the simple present tense, which is inconsistent with the past time frame established by "evaluated the site in March 2023."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BYWPGH', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing an article about urban beekeeping, a student wants to emphasize the economic benefit that rooftop hives can provide to local businesses. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FSIDCU', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Ecologist Tomás Herrera recently completed a seven-year census of amphibian species in the cloud forests of central Panama. His team catalogued thirty-one species across fourteen survey sites, nine of which had never been systematically sampled. <u>Five of the species recorded had not been documented in the region for over two decades.</u> Herrera''s findings have prompted Panama''s Ministry of Environment to designate three new protected corridors linking fragmented habitat patches.', $lyceon_json$[{"key":"A","text":"It highlights a particularly notable finding from the research"},{"key":"B","text":"It challenges a claim made earlier in the text"},{"key":"C","text":"It explains the methodology Herrera's team used during the census"},{"key":"D","text":"It describes the government's response to the study's conclusions"}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence singles out the rediscovery of five species unseen for over twenty years, which is a standout result within the broader census data, so it highlights a particularly notable finding. Nothing in the preceding text presents a claim that the underlined sentence contradicts, ruling out a challenge. The sentence reports a result, not a method, so it does not explain methodology. The government''s response is described in the sentence that follows, not in the underlined sentence itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HV176R', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "tenuous" most nearly mean?', E'Marine biologists studying the coral reefs off the coast of Palau have observed that the relationship between reef fish populations and water temperature is more <u>tenuous</u> than previously assumed. While earlier models predicted a direct correlation, recent data suggest that other variables, such as nutrient runoff and predator density, play equally significant roles in determining fish abundance.', $lyceon_json$[{"key":"A","text":"fragile"},{"key":"B","text":"hostile"},{"key":"C","text":"predictable"},{"key":"D","text":"unprecedented"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a relationship that is weaker and less certain than scientists had believed, making "fragile" the best fit for "tenuous" in this context. "Hostile" implies antagonism, which does not describe a weakened correlation. "Predictable" contradicts the passage''s point that the relationship is less straightforward than expected. "Unprecedented" means never seen before, which is unrelated to the weakness of the connection being described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I8G9H5', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Archaeologist Jun Takahashi proposes that the abandonment of the Ancestral Puebloan settlement at Mesa Verde around 1285 CE was driven primarily by prolonged drought. Tree-ring records from the region show that precipitation fell to its lowest levels in over six centuries during the period 1276–1299, making large-scale agriculture untenable.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ITQF5Q', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "circumscribed" most nearly mean?', E'Historian Mariela Ochoa argues that the influence of nineteenth-century women journalists has been <u>circumscribed</u> by a scholarly tradition that treats their reporting as mere social commentary rather than substantive political analysis. By cataloguing over four hundred editorials from seven metropolitan dailies, Ochoa demonstrates that these writers engaged directly with tariff policy, labor legislation, and electoral strategy—subjects their contemporaries recognized as squarely within the political sphere.', $lyceon_json$[{"key":"A","text":"documented"},{"key":"B","text":"restricted"},{"key":"C","text":"exaggerated"},{"key":"D","text":"celebrated in historical accounts"}]$lyceon_json$::jsonb, 'B', NULL, E'Ochoa''s argument is that scholars have narrowed or limited the perceived influence of women journalists by misclassifying their political work as social commentary; "restricted" captures this sense of confinement. "Documented" means recorded, which is neutral and does not convey the diminishment Ochoa criticizes. "Exaggerated" implies the influence has been overstated, the opposite of Ochoa''s claim. "Celebrated in historical accounts" contradicts the passage''s point that these journalists'' contributions have been undervalued rather than praised.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K1XEOU', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The marine biologist Katarina Petrovic spent eleven months cataloging bioluminescent organisms in the Celebes Sea. Her team identified forty-seven previously undocumented _______ findings were published in a peer-reviewed journal in 2024.', $lyceon_json$[{"key":"A","text":"species, and their"},{"key":"B","text":"species their"},{"key":"C","text":"species, their"},{"key":"D","text":"species and, their"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence contains two independent clauses: "Her team identified forty-seven previously undocumented species" and "their findings were published in a peer-reviewed journal in 2024." Two independent clauses must be joined by a comma plus a coordinating conjunction. "species, and their" correctly uses a comma followed by the coordinating conjunction "and" to join the clauses. "species their" is a run-on sentence with no punctuation or conjunction between the clauses. "species, their" creates a comma splice, joining two independent clauses with only a comma and no conjunction. "species and, their" incorrectly places the comma after the conjunction rather than before it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KI2BIJ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists at the University of Turku have hypothesized that the unusually high species diversity of ground beetles in Finnish old-growth forests is sustained by the structural complexity of decaying logs. Specifically, they propose that logs in advanced stages of decay create distinct microclimates with stable humidity levels, allowing beetle species with narrow moisture tolerances to coexist alongside generalist species that tolerate a wider range of conditions.', $lyceon_json$[{"key":"A","text":"Old-growth forests with a greater density of heavily decayed logs support more beetle species with narrow moisture tolerances than forests with fewer such logs."},{"key":"B","text":"Ground beetle populations in Finnish forests have increased steadily over the past three decades as conservation policies have limited logging activities."},{"key":"C","text":"Generalist beetle species are found in a wider variety of habitats across Finland than specialist beetle species with narrow moisture tolerances."},{"key":"D","text":"The total biomass of decaying logs in old-growth forests exceeds that of younger managed forests by a factor of approximately eleven."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that heavily decayed logs create microclimates enabling beetle species with narrow moisture tolerances to coexist with generalists. A finding that forests with more heavily decayed logs harbor more such specialist species directly supports the proposed mechanism. The finding about beetle populations increasing due to conservation policies addresses population size rather than the specific mechanism linking log decay to species diversity. The finding about generalist species being found in more habitats simply restates a general property of generalists without connecting log structure to specialist coexistence. The finding about total biomass of decaying logs documents a difference in log quantity but does not link that difference to beetle diversity or microclimate effects.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KSAP5B', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Literary scholar Priya Venkatesh contends that the narrative digressions in Olaudah Equiano''s 1789 autobiography are not lapses in craft but deliberate rhetorical strategies. She notes that Equiano interrupts his chronological account at precisely those moments when readers might reduce his experience to a single emotional register—pity, outrage, or admiration.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MBUHG6', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1953, biochemist Erwin Chargaff published data showing that in DNA the quantity of adenine closely matched the quantity of thymine, and likewise guanine matched cytosine. This regularity, later called Chargaff''s rules, was initially dismissed by many crystallographers who considered chemical-composition data irrelevant to determining molecular shape. Within months, however, Watson and Crick incorporated the base-pairing ratios into their double-helix model, vindicating Chargaff''s contribution and demonstrating that composition and structure were inseparable.', $lyceon_json$[{"key":"A","text":"It introduces a scientific finding, describes an initial negative reaction to it, and then explains how the finding was ultimately validated"},{"key":"B","text":"It compares two competing methods of analyzing DNA and argues that one method is superior to the other"},{"key":"C","text":"It presents a biographical overview of Chargaff's career and evaluates the lasting significance of his research program"},{"key":"D","text":"It describes an experimental procedure in detail, identifies a flaw in the methodology, and then explains how later researchers corrected the error to produce more reliable results"}]$lyceon_json$::jsonb, 'A', NULL, E'The text first presents Chargaff''s base-pairing data, then notes that crystallographers dismissed it, and finally shows Watson and Crick vindicating it—a finding, a dismissal, and a validation. The text does not compare two methods or argue for the superiority of one over another. It focuses on a single discovery, not a full biographical overview of Chargaff''s career. No experimental flaw or methodological correction is described; the issue was reception, not methodology.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PHY9DI', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "galvanized" most nearly mean?', E'When the municipal council proposed demolishing the 1920s-era Firehouse No. 7 to make way for a parking structure, the announcement <u>galvanized</u> residents who had never previously attended a city meeting. Within seventy-two hours, a petition bearing over three thousand signatures landed on the mayor''s desk, and a coalition of historians, architects, and neighborhood associations formed to oppose the plan.', $lyceon_json$[{"key":"A","text":"alarmed"},{"key":"B","text":"mystified"},{"key":"C","text":"mobilized"},{"key":"D","text":"placated"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage shows residents springing into organized action—signing petitions and forming coalitions—so "mobilized" captures the sense of being spurred to collective activity. "Alarmed" conveys fear but not the organized response the passage emphasizes. "Mystified" means confused or puzzled, which contradicts the decisive action described. "Placated" means soothed or appeased, the opposite of being stirred to protest.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PYZKDQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In a 2024 paper published in the journal Soil Ecology, geochemist Tomasz Baranski challenged the prevailing assumption that mycorrhizal fungal networks transfer nutrients primarily to closely related plant species. Baranski''s greenhouse experiments with 41 plant pairings showed that nutrient transfer rates between unrelated species were, on average, only 8 percent lower than transfers between congeneric pairs. He attributed this finding to the fungi''s own metabolic incentives: mycorrhizal fungi benefit from maintaining diverse host communities because genetic diversity among hosts reduces the fungi''s vulnerability to species-specific pathogens. Baranski concluded that the so-called ''kin selection'' model of fungal nutrient sharing requires significant revision.', $lyceon_json$[{"key":"A","text":"Baranski's experiments suggest that mycorrhizal fungi share nutrients across unrelated plant species at rates comparable to those among related species, likely because host diversity benefits the fungi themselves."},{"key":"B","text":"Mycorrhizal fungi are vulnerable to pathogens that target specific host species, which has led researchers to study how fungi protect themselves from infection."},{"key":"C","text":"The kin selection model of fungal nutrient sharing was developed to explain why plants growing near relatives tend to receive more resources from soil fungi than isolated plants do."},{"key":"D","text":"Baranski's greenhouse experiments used a larger number of plant pairings than previous studies and therefore produced more statistically reliable results regarding nutrient transfer."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage''s central point is that Baranski found nutrient transfer rates between unrelated species were nearly as high as between related species, and he explains this through the fungi''s own metabolic incentives favoring host diversity. The choice about fungi sharing nutrients comparably across unrelated species captures both the finding and its explanation. The choice about fungi being vulnerable to pathogens seizes on one supporting detail about pathogen vulnerability without connecting it to the main argument about nutrient sharing patterns. The choice describing the kin selection model''s original purpose addresses background context rather than the passage''s central claim, which is that this model needs revision. The choice about Baranski''s study having more pairings introduces a claim about statistical reliability that the passage never makes; the text mentions 41 pairings as a fact but does not compare this to prior studies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QWFDL1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The playwright Miriam Okafor drew inspiration from her childhood in Lagos when writing her critically acclaimed trilogy. In each of the three plays, a young protagonist _______ the tension between traditional family obligations and the desire for personal independence in a rapidly modernizing city.', $lyceon_json$[{"key":"A","text":"navigate"},{"key":"B","text":"navigates"},{"key":"C","text":"navigating"},{"key":"D","text":"having navigated"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject is "a young protagonist," which is singular and requires a singular verb. The sentence is in the present tense, describing what happens in each play. "navigates" is the correct third-person singular present-tense form that agrees with the singular subject and maintains the present tense established by the context. "navigate" is the bare plural form that does not agree with the singular subject "a young protagonist." "navigating" is a present participle that cannot serve as the main verb of the clause without an auxiliary; using it here creates a sentence fragment. "having navigated" is a perfect participial phrase that likewise cannot serve as the main verb without an auxiliary and would also incorrectly shift the action to a completed event.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SFS37J', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall structure of the text?', E'Historian Adaeze Okonkwo has argued that the decline of the Benin Kingdom''s brass-casting tradition in the late nineteenth century was driven primarily by British colonial disruption of trade networks rather than by any internal artistic decline. Supporting this view, metallurgical analyses of brass artifacts from the 1870s and 1880s show no deterioration in alloy composition or casting technique compared to pieces from the kingdom''s sixteenth-century peak. However, art historian Fumihiro Tanaka contends that Okonkwo''s framing overlooks evidence of shifting artistic priorities within the kingdom itself: court records from the 1860s indicate that Oba Adolo redirected guild resources toward ivory carving for diplomatic gifts, reducing the volume of brass commissions well before the British punitive expedition of 1897. Tanaka does not dispute the quality of late-period brass work but argues that the tradition''s diminished output reflected deliberate internal reallocation, not merely external disruption.', $lyceon_json$[{"key":"A","text":"It presents a historian's claim about the cause of an artistic tradition's decline and then introduces a counterargument that attributes the decline to a different factor."},{"key":"B","text":"It describes a metallurgical finding about brass artifacts and then explains how that finding was used to justify British colonial policies in the Benin Kingdom."},{"key":"C","text":"It outlines two historians' agreement that the Benin Kingdom's brass-casting quality remained high and then explores why the tradition eventually ended despite this quality."},{"key":"D","text":"It introduces a debate about whether the Benin Kingdom's brass casting declined in quality during the late nineteenth century and then resolves the debate with metallurgical evidence."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first presents Okonkwo''s claim that colonial disruption caused the decline of brass casting and then introduces Tanaka''s counterargument that internal reallocation of resources was the primary cause. The choice describing a claim followed by a counterargument attributing the decline to a different factor accurately captures this structure. The choice about metallurgical findings justifying colonial policies misreads the role of the metallurgical analysis, which supports Okonkwo''s argument about quality rather than justifying colonial actions. The choice about two historians agreeing and then exploring why the tradition ended mischaracterizes the relationship between Okonkwo and Tanaka as agreement when they actually disagree about the cause of diminished output. The choice about resolving a debate over quality decline misidentifies the central debate; neither historian claims quality declined, and the metallurgical evidence does not resolve the actual disagreement about why output decreased.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UAFOXL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ethnomusicologist Ravi Subramaniam spent three years recording folk songs in the villages of Chhattisgarh. He discovered that many of the melodies he _______ predating the Mughal period, had never been transcribed into any written notation system.', $lyceon_json$[{"key":"A","text":"documented, some"},{"key":"B","text":"documented. Some,"},{"key":"C","text":"documented, some,"},{"key":"D","text":"documented some,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence structure is: "He discovered that many of the melodies he documented, some predating the Mughal period, had never been transcribed." The phrase "some predating the Mughal period" is a nonrestrictive participial phrase that must be set off by commas on both sides because it is parenthetical information inserted between the subject ("melodies he documented") and the verb ("had never been transcribed"). "documented, some," correctly places commas on both sides of this parenthetical element. "documented, some" opens the parenthetical phrase with a comma but fails to close it before "predating," which disrupts the sentence structure. "documented. Some," breaks the sentence after "documented," creating a fragment: "Some, predating the Mughal period, had never been transcribed" loses the subordinate clause begun by "that." "documented some," omits the opening comma, which causes "some predating the Mughal period" to read as the direct object of "documented" rather than as a parenthetical modifier.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WCSO7X', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes how Nakamura would most likely characterize the approach taken by Engström?', E'Text 1: Economist Lars Engström argues that carbon taxes are the most efficient policy instrument for reducing industrial emissions. Analyzing data from twenty-three OECD nations between 2005 and 2019, Engström finds that each ten-dollar increase in the carbon tax rate per metric ton was associated with a 3.1 percent reduction in emissions from the manufacturing sector, a relationship that held even after controlling for GDP growth and energy-price fluctuations.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y0BZQW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Researchers studying the acoustic behavior of humpback whales in the waters near Tonga have observed that male whales modify their songs over the course of each breeding season. Early in the season, males in a given population sing nearly identical versions of the previous year''s song. As weeks pass, individual males introduce variations, and by the season''s end, the song has changed substantially. Crucially, males that deviate too far from the current consensus version attract fewer mating approaches from females. This pattern suggests that female humpback whales ________', $lyceon_json$[{"key":"A","text":"prefer songs that incorporate moderate novelty while remaining recognizable as the shared population song."},{"key":"B","text":"are unable to detect the acoustic differences between early-season and late-season versions of male songs."},{"key":"C","text":"select mates based exclusively on the physical size and age of the singing male rather than on song characteristics."},{"key":"D","text":"produce their own simplified versions of male songs to signal receptivity during the breeding season."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that males gradually modify their songs and that males deviating too far from the consensus version attract fewer females. This implies females favor songs with some variation but not excessive departure from the shared version, supporting the inference that females prefer moderate novelty within the framework of the population song. The choice about females being unable to detect differences contradicts the passage''s implication that females respond selectively to song variations. The choice about females selecting mates based on size and age contradicts the passage''s evidence that song conformity influences mating approaches. The choice about females producing their own songs introduces a behavior not mentioned or implied anywhere in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
